import random

# results[task_id] = 每次运行是否成功（1/0），来自同一批任务的旧/新 Harness 各自多次运行
old_results = {"t1": [1, 1, 0, 1], "t2": [0, 0, 0, 1], "t3": [1, 1, 1, 1]}
new_results = {"t1": [1, 1, 1, 1], "t2": [0, 0, 0, 0], "t3": [1, 0, 1, 1]}


def mean_rate(results):
    return sum(sum(v) / len(v) for v in results.values()) / len(results)


def paired_bootstrap_ci(old, new, n_boot=2000):
    task_ids = list(old.keys())
    diffs = []
    for _ in range(n_boot):
        sample = [random.choice(task_ids) for _ in task_ids]  # 按任务重采样
        old_rate = mean_rate({t: old[t] for t in sample})
        new_rate = mean_rate({t: new[t] for t in sample})
        diffs.append(new_rate - old_rate)
    diffs.sort()
    lo, hi = diffs[int(0.025 * n_boot)], diffs[int(0.975 * n_boot)]
    return lo, hi


lo, hi = paired_bootstrap_ci(old_results, new_results)
print(f"新旧 Harness 成功率差异 95% 置信区间: [{lo:.3f}, {hi:.3f}]")
# 如果置信区间跨过 0，说明差异可能只是噪声，不能断言新 Harness 更好
